import { expect, expectStatus, test } from "../../fixtures";

test.describe("review vendors", () => {
  test("submitting a vendor with all documents extracted moves it to review", { tag: "@REV-01" }, async ({ apiAs, factory }) => {
    // Arrange: a member's draft vendor with w9, insurance_certificate, and contract extracted
    const member = await apiAs("member");
    const { vendor } = await factory.vendorWithDocuments({ as: "member" });

    // Act: the member submits the vendor for review
    const response = await member.post(`/api/vendors/${vendor.id}/submit`);

    // Assert: the response and the stored status both show the vendor in review
    const submitted = await expectStatus<{ id: string; status: string }>(response, 200);
    expect(submitted.status).toBe("in_review");
    const stored = await expectStatus<{ status: string }>(await member.get(`/api/vendors/${vendor.id}`), 200);
    expect(stored.status).toBe("in_review");

    // Assert: the submission is recorded in the audit trail
    const trail = await expectStatus<{ items: { action: string }[] }>(
      await member.get(`/api/vendors/${vendor.id}/audit`),
      200,
    );
    expect(trail.items.map((event) => event.action)).toContain("vendor.submitted");
  });
});
